216	     *  blank from-date with the grade in force on the sheet's today gives no grade. */
217	    @Transactional
218	    public Person update(String sheetId, String user, Long id, long version, String name, String grade,
219	            LocalDate gradeFrom, Integer terms, String contact) {
220	        Person person = people.findByIdAndSheetId(id, sheetId)
221	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
222	        if (person.getVersion() != version) {
