306	                .filter(patron -> asOf == null || patron.madeAsOf(asOf))
307	                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
308	                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
309	    }
310	
311	    /** Each person's holds on the sheet as they stood at the end of a day, in the order they were put
312	     *  on, by person id (null: as they stand now); a person with none is absent. */
313	    public Map<Long, List<PersonHold>> holds(String sheetId, LocalDate asOf) {
314	        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
315	                .filter(hold -> asOf == null || hold.madeAsOf(asOf))
316	                .collect(Collectors.groupingBy(PersonHold::getPersonId));
317	    }
318	
319	    /** The ids of the people a user watched on the sheet at the end of a day (null: now). */
320	    public Set<Long> watchedIds(String sheetId, String user, LocalDate asOf) {
321	        Set<Long> now = watchedIds(sheetId, user);
322	        return asOf == null ? now : history.watched(sheetId, user, now, asOf);
323	    }
324	
325	    /** The sheet's people as they stood at the end of a day, in the order they were added: those added
326	     *  by then, each with the name, own terms, retirement and contact they had then (null: as they stand now). */
327	    public List<Person> list(String sheetId, LocalDate asOf) {
328	        if (asOf == null) {
329	            return list(sheetId);
330	        }
331	        Map<Long, History.PersonThen> then = history.people(sheetId, asOf);
332	        return list(sheetId).stream().filter(person -> person.onSheetAsOf(asOf)).map(person -> {
333	            History.PersonThen was = then.get(person.getId());
334	            return was == null ? person : person.asItWas(was.name(), was.terms(), was.retiredFrom(), was.contact());
335	        }).toList();
336	    }
337	
338	    /** A person's patron ids, in the order they were named. */
339	    public List<Long> patronIds(Long personId) {
340	        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
341	    }
342	
343	    /** Name another person on the sheet as a person's patron; refused for the person themselves and
344	     *  for someone already their patron. */
345	    @Transactional
346	    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
347	        Person person = people.findByIdAndSheetId(id, sheetId)
348	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
349	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
350	                .orElseThrow(() -> new NoSuchElementException("No person " + patronId + " on sheet " + sheetId));
351	        if (person.getId().equals(patron.getId())) {
352	            throw new PatronRefusedException(person.getName() + " cannot be their own patron");
353	        }
354	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
355	            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
356	        }
357	        patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId(), sheets.today(sheetId)));
358	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
359	                + " patron=" + patron.getName());
360	        return person;
361	    }
362	
363	    /** Start or stop a user watching a person; a person already in that state is left as they are,
364	     *  writing nothing. */
365	    @Transactional
366	    public Person watch(String sheetId, String user, Long id, boolean on) {
367	        Person person = people.findByIdAndSheetId(id, sheetId)
368	                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
369	        var existing = watches.findByPersonIdAndUser(id, user);
370	        if (on && existing.isEmpty()) {
371	            watches.saveAndFlush(new PersonWatch(sheetId, id, user));
372	            history.watchSet(sheetId, id, user, true);
373	            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
374	        } else if (!on && existing.isPresent()) {
375	            watches.delete(existing.get());
376	            watches.flush();
377	            history.watchSet(sheetId, id, user, false);
378	            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
379	        }
380	        return person;
381	    }
382	
383	    /** The ids of the people a user watches on the sheet. */
384	    public Set<Long> watchedIds(String sheetId, String user) {
385	        return watches.findBySheetIdAndUser(sheetId, user).stream().map(PersonWatch::getPersonId)
386	                .collect(Collectors.toSet());
387	    }
388	
389	    /** Whether a user watches a person. */
390	    public boolean watches(Long personId, String user) {
391	        return watches.findByPersonIdAndUser(personId, user).isPresent();
392	    }
393	
394	    /** A person's watchers, in the order they started watching. */
395	    public List<String> watchers(Long personId) {
396	        return watches.findByPersonIdOrderByIdAsc(personId).stream().map(PersonWatch::getUser).toList();
397	    }
398	
399	    private void record(String event, String sheetId, String user, Person person, String grade, String terms) {
400	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
401	                + " name=" + person.getName() + " grade=" + grade + terms);
402	    }
403	
404	    /** A contact as kept: trimmed and lower-cased; null for a blank one. */
405	    private static String contactKey(String contact) {
406	        if (contact == null || contact.isBlank()) {
407	            return null;
408	        }
409	        return contact.trim().toLowerCase(Locale.ROOT);
410	    }
411	
412	    private void requireFreeContact(String sheetId, String contact, Long exceptId) {
413	        if (contact != null && people.contactInUse(sheetId, contact, exceptId)) {
414	            throw new ContactInUseException(contact);
415	        }
416	    }
417	
418	    private void requireFreeName(String sheetId, String name, Long exceptId) {
419	        if (people.nameInUse(sheetId, name, exceptId)) {
420	            throw new NameInUseException(name);
421	        }
422	    }
423	}
