482	     *  when (null when not), and the holds put on them in the order they were, and the ids of their patrons in the order
483	     *  they were named, and whether the signed-in user watches them, and their own terms (null for none), and their contact (null for none). */
484	    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
