486	            List<HoldView> holds, List<Long> patronIds, boolean watched, Integer terms, String contact) {
487	        public static PersonView of(Person person, List<PersonGrade> grades, LocalDate today,
488	                StatementSummary statements, List<PersonHold> holds, List<Long> patronIds, boolean watched) {
489	            return new PersonView(person.getId(), person.getName(), PersonGradeService.gradeOn(grades, today),
490	                    grades.stream().map(GradeView::of).toList(), person.getVersion(), statements.count(),
491	                    statements.lastDueTotal(), statements.lastDate(), person.isRetired(), person.getRetiredFrom(),
492	                    holds.stream().map(HoldView::of).toList(), patronIds, watched, person.getTerms(),
