562	            @RequestHeader(value = SignedInUser.HEADER, required = false) String user,
563	            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
564	        String sheet = sheetId.trim();
565	        LocalDate asOf = AsOf.parse(asOfHeader);
566	        Set<Long> watched = user == null ? Set.of() : service.watchedIds(sheet, SignedInUser.decode(user), asOf);
567	        Map<Long, StatementSummary> summaries = statements.summaries(sheet, asOf);
568	        Map<Long, List<Long>> patrons = service.patronIds(sheet, asOf);
569	        Map<Long, List<PersonGrade>> given = grades.bySheet(sheet, asOf);
570	        Map<Long, List<PersonHold>> holds = service.holds(sheet, asOf);
571	        LocalDate today = asOf != null ? asOf : sheets.today(sheet);
572	        return service.list(sheet, asOf).stream()
573	                .map(p -> PersonView.of(p, given.getOrDefault(p.getId(), List.of()), today,
574	                        summaries.getOrDefault(p.getId(), StatementSummary.NONE),
575	                        holds.getOrDefault(p.getId(), List.of()),
