640	    /** Start or stop the signed-in user watching a person. */
641	    @PostMapping("/{id}/watch")
642	    public PersonView watch(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
643	            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated WatchRequest request) {
644	        String sheet = sheetId.trim();
645	        String by = SignedInUser.decode(user);
646	        return withStatements(service.watch(sheet, by, id, request.watched()), by);
