649	    /** A date that is not a real yyyy-mm-dd date, or a hold that ends before it starts, is refused. */
650	    @ExceptionHandler({HttpMessageNotReadableException.class, HoldRefusedException.class})
651	    @ResponseStatus(HttpStatus.BAD_REQUEST)
652	    public void unreadable() {
653	    }
