656	    @ExceptionHandler(StalePersonException.class)
657	    @ResponseStatus(HttpStatus.PRECONDITION_FAILED)
658	    public PersonView stale(StalePersonException e, HttpServletRequest request) {
659	        String user = request.getHeader(SignedInUser.HEADER);
660	        return withStatements(e.getCurrent(), user == null ? null : SignedInUser.decode(user));
661	    }
662	
663	    private PersonView withStatements(Person person, String user) {
664	        return PersonView.of(person, grades.of(person.getId()), sheets.today(person.getSheetId()),
665	                statements.summary(person.getSheetId(), person.getId()), service.holds(person.getId()),
666	                service.patronIds(person.getId()), user != null && service.watches(person.getId(), user));
