670	    @ExceptionHandler(ObjectOptimisticLockingFailureException.class)
671	    @ResponseStatus(HttpStatus.PRECONDITION_FAILED)
672	    public void raced() {
673	    }
674	
675	    @ExceptionHandler(NoSuchElementException.class)
676	    @ResponseStatus(HttpStatus.NOT_FOUND)
677	    public void notFound() {
678	    }
679	
680	    /** The name or contact is already in use on the sheet, or the patron may not be named; a concurrent
681	     *  save is caught by the unique index. */
682	    @ExceptionHandler({NameInUseException.class, ContactInUseException.class, PatronRefusedException.class,
683	            DataIntegrityViolationException.class})
684	    @ResponseStatus(HttpStatus.CONFLICT)
685	    public void nameInUse() {
686	    }
